-- Re-check capacity when restoring a cancelled/no-show appointment. Existing ACL stays unchanged.
CREATE OR REPLACE FUNCTION public.ludia_guard_appointment_staff_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_timezone text := 'Asia/Seoul'; v_local_start timestamp; v_local_end timestamp; v_rule public.ludia_staff_work_rules%rowtype; begin if new.staff_user_id is null or new.status in ('cancelled','no_show') then return new; end if; if tg_op='UPDATE' and new.staff_user_id is not distinct from old.staff_user_id and new.starts_at is not distinct from old.starts_at and new.ends_at is not distinct from old.ends_at and old.status not in ('cancelled','no_show') then return new; end if; perform pg_advisory_xact_lock(hashtextextended(new.salon_id::text||':staff:'||new.staff_user_id::text,0)); if not exists(select 1 from public.ludia_salon_members m where m.salon_id=new.salon_id and m.user_id=new.staff_user_id and m.is_active) then raise exception using message='LUDIA_AVAILABILITY:inactive_staff',errcode='P0001'; end if; select coalesce(timezone,'Asia/Seoul') into v_timezone from public.ludia_salons where id=new.salon_id; v_local_start:=new.starts_at at time zone v_timezone; v_local_end:=new.ends_at at time zone v_timezone; if v_local_start::date<>v_local_end::date then raise exception using message='LUDIA_AVAILABILITY:outside_work_hours',errcode='P0001'; end if; select * into v_rule from public.ludia_staff_work_rules where salon_id=new.salon_id and staff_user_id=new.staff_user_id and weekday=extract(dow from v_local_start)::smallint; if found and (not v_rule.is_working or v_rule.starts_at is null or v_rule.ends_at is null or v_local_start::time<v_rule.starts_at or v_local_end::time>v_rule.ends_at) then raise exception using message='LUDIA_AVAILABILITY:outside_work_hours',errcode='P0001'; end if; if exists(select 1 from public.ludia_staff_time_off t where t.salon_id=new.salon_id and t.staff_user_id=new.staff_user_id and t.starts_at<new.ends_at and t.ends_at>new.starts_at) then raise exception using message='LUDIA_AVAILABILITY:time_off',errcode='P0001'; end if; if exists(select 1 from public.ludia_appointments a where a.salon_id=new.salon_id and a.staff_user_id=new.staff_user_id and a.status not in ('cancelled','no_show') and a.id<>new.id and a.starts_at<new.ends_at and a.ends_at>new.starts_at) then raise exception using message='LUDIA_AVAILABILITY:appointment_conflict',errcode='P0001'; end if; return new; end $function$;
